  'cameras/camera_follow': {
    description: 'Center a live process’s origin in the camera viewport after each simulation tick. Successful set or move calls cancel following. If the target terminates, the camera keeps its last position.',
    params: [['camera?', 'An explicit camera. Omit this argument to track with the main camera.'],
      ['target', 'A live process handle.']],
    example: 'camera_follow(self)\ncamera_follow(view, self)',
    related: ['camera_set', 'camera_move', 'camera_create'],
  },
  'cameras/camera_create': {
    description: 'Create a managed explicit camera. Assign it to `self.camera` to select it for a process.',
    params: [['options', 'Required table. World coordinates `x` and `y` each default to zero and must be finite with magnitude at most `FLT_MAX / 64`. `viewport` takes a region descriptor and defaults to the full logical window. Unknown fields raise an error.']],
    example: 'local view = camera_create {\n  x = 100, y = 50,\n  viewport = region {x = 40, y = 60, width = 400, height = 300}\n}',
    related: ['region', 'camera_set', 'camera_follow', 'camera_position', 'camera_destroy'],
  },
  'cameras/camera_set': {
    description: 'Set an absolute world position. A successful call cancels following.',
    params: [['camera?', 'An explicit camera. Omit this argument to use the main camera.'],
      ['x', 'New x.'], ['y', 'New y.']],
    example: 'camera_set(100, 50)\ncamera_set(view, 120, 80)',
    related: ['camera_move', 'camera_follow', 'camera_position'],
  },
  'cameras/camera_move': {
    description: 'Add a relative displacement to the camera’s world position. A successful call cancels following.',
    params: [['camera?', 'An explicit camera. Omit this argument to use the main camera.'],
      ['dx', 'Horizontal delta.'], ['dy', 'Vertical delta.']],
    example: 'camera_move(10, 0)\ncamera_move(view, 10, 0)',
    related: ['camera_set', 'camera_follow', 'scroll'],
  },
  'cameras/camera_position': {
    description: 'Return the camera’s world position as two numbers, x and y. The main camera is used by default.',
    params: [['camera?', 'A camera from `camera_create`.']],
    example: 'local x, y = camera_position(view)',
    related: ['camera_set', 'camera_move'],
  },

  'cameras/camera_destroy': {
    description: 'Close an explicit camera and stop following. Repeating the call is safe. Processes using the closed view stop drawing until they select another view.',
    params: [['camera', 'A camera handle from `camera_create`.']],
    example: 'camera_destroy(view)',
    related: ['camera_create', 'camera_position'],
  },

